for (const [id, langs] of Object.entries(TRACK_POOLS)) {
  const part = (from, to) => Object.fromEntries(VOICE_LANGS.map((l) => [l, langs[l].slice(from, to)]));
  POOLS[`intro.${id}`] = { voice: 'a', mood: 'plain', ...part(0, 2) };
  POOLS[`col.${id}`] = { mood: 'dry', ...part(2, 5) };
}

export function spoken(lang, text) {
  let out = text;
  for (const [from, to] of SPOKEN[lang] ?? []) out = out.split(from).join(to);
  return out;
}

// Every clip of a language. id: pool.line, then the driver for a `who` pool, then the voice for a line made in both.
export function clipsFor(lang) {
  const out = [];
  for (const [pool, P] of Object.entries(POOLS)) {
    P[lang].forEach((line, n) => {
      const voices = P.voice === 'both' ? ['a', 'b'] : [P.voice ?? (n % 2 ? 'b' : 'a')];
      const karts = P.who ? Object.keys(DRIVERS) : [null];
      for (const voice of voices) for (const kart of karts) {
        const text = kart ? line.replace('{who}', DRIVERS[kart]) : line;
        const id = [pool, n, kart, P.voice === 'both' ? voice : null].filter((x) => x !== null).join('.');
        out.push({ id, pool, n, kart, voice, mood: P.mood ?? 'plain', text, say: spoken(lang, text), name: BOOTH[lang][voice] });
      }
    });
  }
  return out;
}
